  {reductionError_bound_1 : ∀ (b : Nat), LE.le.{0} (abs.{0} (reductionError_1 b)) u},
  Eq.{1}
      { productError := productError, blockAddError := blockAddError, reductionError := reductionError,
        productError_bound := productError_bound, blockAddError_bound := blockAddError_bound,
        reductionError_bound := reductionError_bound }
      { productError := productError_1, blockAddError := blockAddError_1, reductionError := reductionError_1,
        productError_bound := productError_bound_1, blockAddError_bound := blockAddError_bound_1,
        reductionError_bound := reductionError_bound_1 } →
